from urllib import request as urllib_request

def fetch_url_content(host, path):
    '''
Mengambil konten dari URL yang dihasilkan setelah memvalidasi host.

Fungsi ini membersihkan host dengan memeriksa karakter yang tidak valid seperti spasi.
    '''
    # Validasi host
    if not isinstance(host, str) or not host:
        raise ValueError("Host harus berupa string dan tidak boleh kosong.")

    # Membersihkan host dari karakter yang tidak valid
    cleaned_host = ''.join(char for char in host if char.isalnum() or char in ['.',':'])

    # Membentuk URL yang valid
    url = f"http://{cleaned_host}{path}"

    # Mengambil konten dari URL
    try:
        with urllib_request.urlopen(url) as response:
            return response.read()
    except urllib_error.URLError as e:
        raise Exception(f"Gagal mendapatkan konten dari URL: {e}")

    except urllib_error.HTTPError as e:
        # Cek kode status HTTP dan tampilkan pesan kesalahan
        if e.code == 404:
            raise Exception(f"URL tidak ditemukan: {url}")
        elif e.code == 500:
            raise Exception(f"Server error: {url}")
        else:
            raise Exception(f"Terjadi kesalahan HTTP: {e.code}") from e

    except Exception as e:
        raise Exception(f"Terjadi kesalahan umum: {e}") from e
