import re

def validate_token_header(header):
    '''
    Mengesahkan header token untuk memastikan algoritma disokong.

    Fungsi ini memeriksa jika medan 'alg' dalam header mengandungi 'HS256'.
    '''
    # Cek apakah header adalah dictionary atau string
    if isinstance(header, str):
        header_dict = {}
        for part in header.split(';'):
            key, value = part.strip().split('=', 1)
            header_dict[key] = value
    elif isinstance(header, dict):
        header_dict = header
    else:
        raise ValueError("Header harus berupa dictionary atau string")

    # Mencari nilai 'alg' dalam header
    alg_value = header_dict.get('alg')

    # Periksa apakah 'alg' adalah HS256
    if alg_value == 'HS256':
        return True
    else:
        return False
