import tarfile
import os

def extract_member(tar_path, member_name, destination):
    '''
Εξάγει ένα συγκεκριμένο μέλος από ένα αρχείο tar.

Η συνάρτηση ελέγχει αν το όνομα του μέλους ξεκινά με μια κάθετο για να αποτρέψει απόλυτες διαδρομές.
    '''
    if not tar_path.endswith('.tar'):
        raise ValueError("Το αρχείο πρέπει να έχει το χτήριο '.tar'.")

    if not os.path.exists(tar_path):
        raise FileNotFoundError(f"Το αρχείο {tar_path} δεν βρέθηκε.")

    try:
        with tarfile.open(tar_path, 'r') as tar:
            # Check for absolute path in member name
            if os.path.isabs(member_name):
                absolute_path = os.path.join(destination, member_name)
                tar.extract(absolute_path)
            else:
                tar.extract(member_name, path=destination)

    except tarfile.ExtractError as e:
        raise Exception(f"Προβλήματα κατά την εξαγωγή: {e}")
