import os
from collections import deque

class MailcapMatcher:
    def __init__(self, mailcap_file=None):
        self.mailcap_file = mailcap_file
        self.mailcaps = {}
        if mailcap_file:
            self.load_mailcaps(mailcap_file)

    def load_mailcaps(self, file_path):
        with open(file_path, 'r') as file:
            for line in file:
                line = line.strip()
                if line and not line.startswith('#'):
                    parts = line.split('\t')
                    if len(parts) >= 2:
                        capname, default = parts[:2]
                        self.mailcaps[capname] = {
                            'default': default,
                            'commands': []
                        }
                        for command in parts[2:]:
                            self.mailcaps[capname]['commands'].append(command)

    def get_mailcap(self, capname):
        return self.mailcaps.get(capname, None)

    def find_match(self, mime_type, filename, param_buffer):
        best_match = None
        best_score = float('-inf')

        # Use a deque to simulate a stack-like behavior
        candidates = deque([self.get_mailcap(name) for name in self.mailcaps if name.startswith(mime_type)])

        while candidates:
            mailcap = candidates.popleft()
            if mailcap is None:
                continue

            score = 0
            for command in mailcap['commands']:
                parts = command.split(';')
                if len(parts) == 2:
                    cmd_name, condition = parts
                    if eval(condition, {'filename': filename, 'param_buffer': param_buffer}):
                        score += 1

            if score > best_score:
                best_match = mailcap
                best_score = score

        return best_match

# Example usage
