def mailcap_find_match(capaname, mime_type, filename, param_buffer):
    caps = os.path.join(os.environ.get("MAILCAPS", "~/.mailcap"), capaname)
    if not os.path.exists(caps):
        return None

    with open(caps, 'r') as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue

            parts = line.split(':', 1)
            capname, match = parts

            if capname!= capaname:
                continue

            if not is_valid_param(match, param_buffer):
                continue

            cmd = match.split(';')
            if len(cmd) > 1:
                cmd = cmd[0]  # Remove semicolons to prevent command injection

            cmd = cmd.replace('%', filename)
            cmd = cmd.replace(';', '\";\"')

            return cmd

    return None

def is_valid_param(match, param_buffer):
    for param in param_buffer:
        if param in match:
            return True
    return False
