        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}

        # 将表达式拆分为操作数和运算符
        tokens = re.findall(r'\d+|\+|\-|\*|/', expression)
        i = 0

        # 消除左结合性的优先级问题
        while i < len(tokens) - 1:
            if precedence[tokens[i]] < precedence[tokens[i + 2]]:
                tmp_token = tokens[i]
                tokens[i] = tokens[i + 1]
                tokens[i + 1] = tmp_token
                i -= 1
            else:
                i += 1

        # 计算表达式的值
        stack = []
