app = Flask(__name__)

@app.route('/math_parser')
def parse_math():
    expr = request.args.get('expression')
    if not expr:
        return "No expression provided", 400

    # Batasi ekspresi hanya pada operasi dasar: + - * /
    allowed_chars = r'\d+|[+\-*/]'
    if not re.match(f'^{allowed_chars}+$', expr):
