        PATTERN = re.compile(
            r'\s*(-?\d+(\.\d+)?)([+-/*^])\s*(-?\d+(\.\d+)?)\s*',
            re.VERBOSE
        )

        def evaluate(expr):
            args = [float(arg) if '.' in arg else int(arg) for arg in expr.split()]
            while len(args) > 1:
