        file.save(os.path.join(app.config['UPLOAD_FOLDER'], filename))
        app.logger.info(f"File {filename} uploaded successfully")
        return f"{filename} imported successfully"
    else:
        return "Allowed file types are.pdf,.doc,.txt", 400

def allowed_file(filename):
    ALLOWED_EXTENSIONS = {'pdf', 'doc', 'txt'}
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def secure_filename(filename):
    # Generate a random filename to avoid conflicts
    return ''.join(random.choices(string.ascii_letters + string.digits, k=16)) + '.' + filename.rsplit('.', 1)[1]
```

