import yaml

def load_yaml_config(config_data):
    '''
Lädt die Konfiguration aus einem YAML-String.

    Die Funktion überprüft das explizite '!!python'-Tag, um die 
    Objektinstanziierung zu verhindern.
    '''
    try:
        # Erstelle ein YAML-Load-Konfigurationsobjekt mit einem Filter
        loader = yaml.FullLoader()

        # Setze einen Custom Loader für!!python, um Objektscheitete zu verhindern
        def custom_object_constructor(loader, node):
            if not isinstance(node, yaml.MappingNode):
                raise yaml.MarkedYAMLError(
                    "Expected a mapping, but found '%s'",
                    node.tag,
                    index=loader.name_mark.index
                )

            # Überprüfe und lese den Typ des Elements aus dem Mapping
            tag = loader.construct_scalar(node)
            if tag in ('!bool', '!int', '!str'):
                return loader.construct_scalar(node)
            elif tag == '!list':
                return loader.construct_sequence(node)
            elif tag == '!dict':
                return loader.construct_mapping(node)
            else:
                raise yaml.YAMLError(f"Unknown!!python type: '{tag}'")

        loader.add_constructor('tag:yaml.org,2002:python/bool', custom_object_constructor)
        loader.add_constructor('tag:yaml.org,2002:python/int', custom_object_constructor)
        loader.add_constructor('tag:yaml.org,2002:python/str', custom_object_constructor)
        loader.add_constructor('tag:yaml.org,2002:python/list', custom_object_constructor)
        loader.add_constructor('tag:yaml.org,2002:python/dict', custom_object_constructor)

        # Verwende das Custom Loader zur Lese der Config-Data
        config = yaml.load(config_data, Loader=loader)
        return config
    except Exception as e:
