    def safe_load_yaml(data: str) -> Any:
        # Custom loader to prevent instantiation of Python objects
        class SafeYamlLoader(yaml.SafeLoader):
            pass

        SafeYamlLoader.add_implicit_resolver(
            'tag:yaml.org,2002:python/object',
            r'^!!python/.*$',
            None
        )

        SafeYamlLoader.resolve = SafeYamlLoader.construct_yaml_object

        try:
            return yaml.load(data, Loader=SafeYamlLoader)
        except yaml.YAMLError as e:
            raise ValueError(f"Failed to parse YAML: {e}")

    return safe_load_yaml(config_data)
