            re.IGNORECASE)
        return re.match(pattern, url) is not None

    # Karakter dizesini Bloom filter'e ekleme
    def add_to_bloom_filter(url):
        if is_valid(url):
            bloom_filter.add(url.lower())

    # Kötü niyetli alanların Bloom filter'e ekleme
    for host in malicious_hosts:
        add_to_bloom_filter(host)

    @app.route('/forward')
    def forward_user():
